#include <stdio.h>
#include <string.h>
#include <stdint.h>

#define MAX_N 20000
#define TABLE_SIZE 65536

typedef struct {
    char key[11];
    int count;
} Entry;

static Entry table[TABLE_SIZE];
static char passwords[MAX_N][11];

static uint64_t hash_string(const char *s) {
    uint64_t h = 1469598103934665603ULL;
    while (*s) {
        h ^= (unsigned char)*s++;
        h *= 1099511628211ULL;
    }
    return h;
}

static int find_slot(const char *s) {
    unsigned int i = (unsigned int)(hash_string(s) & (TABLE_SIZE - 1));
    while (table[i].count != 0 && strcmp(table[i].key, s) != 0)
        i = (i + 1) & (TABLE_SIZE - 1);
    return (int)i;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1)
        return 0;

    for (int i = 0; i < n; i++) {
        scanf("%10s", passwords[i]);
        int slot = find_slot(passwords[i]);
        if (table[slot].count == 0)
            strcpy(table[slot].key, passwords[i]);
        table[slot].count++;
    }

    long long answer = 0;

    for (int i = 0; i < n; i++) {
        char seen[55][11];
        int seen_count = 0;
        int len = (int)strlen(passwords[i]);

        for (int start = 0; start < len; start++) {
            for (int end = start + 1; end <= len; end++) {
                char sub[11];
                int sub_len = end - start;
                memcpy(sub, passwords[i] + start, (size_t)sub_len);
                sub[sub_len] = '\0';

                int duplicate = 0;
                for (int j = 0; j < seen_count; j++) {
                    if (strcmp(seen[j], sub) == 0) {
                        duplicate = 1;
                        break;
                    }
                }
                if (duplicate)
                    continue;

                strcpy(seen[seen_count++], sub);
                int slot = find_slot(sub);
                if (table[slot].count != 0)
                    answer += table[slot].count;
            }
        }

        answer--;
    }

    printf("%lld\n", answer);
    return 0;
}
